// FireRed's own gBagPockets[] index order (item.c: gBagPockets[POCKET_X-1] =
// ...). Every FireRed-engine config (rev0/rev1/Unbound/Gaia/Radical Red)
// shares this - none of them are known to reorder the bag pockets array.
val FIRERED_BAG_POCKET_ORDER: List<Int> by lazy { listOf(POCKET_ITEMS, POCKET_KEY_ITEMS, POCKET_POKE_BALLS, POCKET_TM_HM, POCKET_BERRIES) }

// struct Pokedex in SaveBlock2 (+0x18: owned[52] at +0x10, seen[52] at +0x44) + SaveBlock1's two
// anti-cheat copies of seen.
val FIRERED_DEX_FLAGS: DexFlags by lazy {
    DexFlags(
        block = DexFlagBlock.SAVE_BLOCK_2,
        seen = 0x5CL,
        caught = 0x28L,
        bytes = 52,
        seenCopies = listOf(0x5F8L, 0x3A18L),
    )
}

